168: /**
169:  * Encode raw RGBA pixels (as returned by Tauri's native clipboard readImage)
170:  * to PNG bytes via an offscreen canvas, so a pasted image can be embedded or
171:  * saved like a file-picked one.
172:  */
173: async function rgbaToPng(rgba: Uint8Array, width: number, height: number): Promise<Uint8Array | null> {
174:     const canvas = document.createElement('canvas');
175:     canvas.width = width;
176:     canvas.height = height;
177:     const ctx = canvas.getContext('2d');
178:     if (!ctx) return null;
179:     ctx.putImageData(new ImageData(new Uint8ClampedArray(rgba), width, height), 0, 0);
180:     const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));
181:     if (!blob) return null;
182:     return new Uint8Array(await blob.arrayBuffer());
183: }
