190: async function showServerBlockedDialog(details: string): Promise<void> {
191:     const { message: dialogMessage } = await import('@tauri-apps/plugin-dialog');
192:     const body =
193:         "CalcpadCE's calculation server could not start.\n\n"
194:         + 'The editor still works, but preview, linting, and PDF/Word export '
195:         + 'need the server. Choose Server → Restart Server to try again.\n\n'
196:         + `Details: ${details}`;
