198:         await dialogMessage(body, {
199:             title: 'CalcpadCE server unavailable',
200:             kind: 'warning',
201:             okLabel: 'OK',
202:         });
203:     } catch {
204:         // dialog can throw if the runtime is tearing down — the buffered log
205:         // line in the Output panel is the fallback.
206:     }
207: }
