209: async function showConfigInvalidDialog(details: string): Promise<'retry' | 'ignore' | null> {
210:     const { message: dialogMessage } = await import('@tauri-apps/plugin-dialog');
211:     const body =
212:         "CalcpadCE's calculation server could not read its settings file.\n\n"
213:         + `${details}\n\n`
214:         + 'Fix the file, then choose Retry to load it again. Choose Ignore to start '
215:         + 'the server with default settings.';
216:     try {
217:         const choice = await dialogMessage(body, {
218:             title: 'Invalid appsettings.json',
219:             kind: 'error',
220:             buttons: { ok: 'Retry', cancel: 'Ignore' },
221:         });
222:         // Some platforms report the custom label, others the default button name.
223:         return choice === 'Retry' || choice === 'Ok' ? 'retry' : 'ignore';
224:     } catch {
