241: async function bootstrap(): Promise<void> {
242:     let serverUrl: string;
243:     let isPrimaryWindow = true;
244:     let windowLabel = 'main';
245:     const appVersion = import.meta.env.VITE_APP_VERSION;
246:     let bridge: MessageBridge | null = null;
247:     let tauriBridge: import('./services/tauri-bridge').TauriMessageBridge | null = null;
248:     let serverManager: import('./services/server-manager').TauriServerManager | null = null;
249:     // Server-manager log lines that arrive before the Output panel mounts
250:     // get buffered here, then flushed when appInstance is ready.
251:     const pendingServerLogs: { msg: string; level?: CalcpadLogLevel }[] = [];
252:     // Raw stdout/stderr lines from the Calcpad.Server sidecar (Rust's
253:     // `server-log` event), buffered the same way for the same reason.
254:     const pendingServerRawLogs: { line: string; stream: 'stdout' | 'stderr' }[] = [];
255: 
256:     if (isTauri) {
257:         windowLabel = (await import('@tauri-apps/api/window')).getCurrentWindow().label;
258:         const { invoke } = await import('@tauri-apps/api/core');
259:         const { listen } = await import('@tauri-apps/api/event');
260:         const updatePrimaryWindow = (label: string) => {
261:             isPrimaryWindow = windowLabel === label;
262:             serverManager?.setAutoRestartEnabled(isPrimaryWindow);
263:         };
264:         await listen<string>('primary-window-changed', event => updatePrimaryWindow(event.payload));
265:         updatePrimaryWindow(await invoke<string>('primary_window'));
266:         // Tauri desktop: the Rust layer owns the Calcpad.Server sidecar
267:         // (spawn, kill on exit, port discovery). This manager just tracks
268:         // its URL and surfaces crashes to the Output panel.
269:         const { TauriServerManager } = await import('./services/server-manager');
270:         // Only one window may auto-restart a crashed sidecar — `server-crashed` is
271:         // broadcast, so both would race to respawn it.
272:         serverManager = new TauriServerManager({
273:             appendLine: (msg: string, level?: CalcpadLogLevel) => pendingServerLogs.push({ msg, level }),
274:         }, isPrimaryWindow);
275:         serverManager.onServerLog = (line: string, stream: 'stdout' | 'stderr') => {
276:             pendingServerRawLogs.push({ line, stream });
277:         };
278: 
279:         // The server is shared, so one dialog is enough; the manager already logged the reason.
280:         serverManager.onStartupBlocked = (details: string) => {
281:             if (isPrimaryWindow) void showServerBlockedDialog(details);
282:         };
283:         const manager = serverManager;
284:         serverManager.onConfigInvalid = (details: string) => {
285:             if (isPrimaryWindow) void resolveConfigInvalid(manager, details);
286:         };
287: 
288:         try {
289:             await serverManager.start();
290:         } catch (err) {
291:             if (!serverManager.startFailureReported) {
292:                 const msg = err instanceof Error ? (err.stack ?? err.message) : String(err);
293:                 pendingServerLogs.push({ msg: `[bootstrap] Server failed to start: ${msg}`, level: 'error' });
294:             }
295:             console.error('[bootstrap] Server failed to start:', err);
296:         }
297:         serverUrl = serverManager.getBaseUrl() || '';
298: 
299:         const { TauriMessageBridge } = await import('./services/tauri-bridge');
300:         tauriBridge = new TauriMessageBridge(serverUrl);
301:         tauriBridge.api.setAuthToken(serverManager.getAuthToken());
302:         (window as any).calcpadBridge = tauriBridge;
303:     } else {
304:         // Pure web: use in-process web bridge
305:         serverUrl = getServerUrl();
306:         bridge = new MessageBridge(serverUrl);
307:         (window as any).calcpadBridge = bridge;
308:     }
309: 
310:     const activeBridge = tauriBridge ?? bridge!;
311:     activeBridge.programVersion = appVersion;
312:     // Last session's panes, result mode and open files, stored apart from the settings.
313:     const workspace = await WorkspaceStateStore.load(isTauri);
314: 
315:     // Initialize the platform messaging (reads VITE_PLATFORM='web')
316:     initMessaging();
317: 
318:     // The base message bridge's handleGoToLine looks up the editor via
319:     // window.monaco (matches the vscode-webview convention). Expose it here so
320:     // sidebar tabs (TOC) can post `goToLine` and reach Monaco.
321:     (window as any).monaco = monaco;
322: 
323:     // Auto follows the OS culture on desktop; the webview language is the fallback.
324:     if (isTauri) {
325:         try {
326:             setCurrentCulture((await osLocale()) ?? undefined);
327:         } catch {
328:             // Keep the browser/navigator fallback.
329:         }
330:     }
331: 
332:     // Mount the main app layout
333:     const app = createApp(App, { isDesktop: isTauri });
334:     const i18n = createCalcpadI18n(readLocaleSetting());
335:     app.use(i18n);
336:     if (isTauri) {
337:         const syncMenu = () => {
338:             const { t } = i18n.global as unknown as Composer;
339:             void invoke('set_menu_labels', { labels: menuLabels(t) }).catch(() => {});
340:         };
341:         const localeRef = i18n.global.locale as unknown as Ref<string>;
342:         syncMenu();
343:         watch(localeRef, syncMenu);
344:     }
345:     const appInstance = app.mount('#app') as any;
346: 
347:     // Let the bridge prompt via the in-app quick-pick modal (image storage mode).
348:     activeBridge.setQuickPick(async ({ title, placeholder, options }) => {
349:         const index = await appInstance.showQuickPick({
350:             title,
351:             placeholder,
352:             options: options.map((o: { label: string; detail?: string }) => ({ label: o.label, detail: o.detail })),
353:         });
354:         return index == null ? null : options[index].value;
355:     });
