357:     // Wait for DOM to render, then set up the editor group(s)
358:     await nextTick();
359: 
360:     registerCalcpadLanguage();
361:     registerCalcpadTheme();
362: 
363:     // Apply the persisted app theme before Monaco initializes so the editor
364:     // renders with the right theme first paint. The desktop bridge loads its
365:     // settings asynchronously, so wait for it; the web bridge is synchronous.
366:     if (tauriBridge) await tauriBridge.ready;
367:     setAppTheme(coerceAppTheme(activeBridge.getStoredColorTheme()));
368:     // Before the buffered startup lines are flushed into the Output panel below, so they are
369:     // filtered against the level the user actually chose rather than the default.
370:     setLogLevel(coerceLogLevel((activeBridge as unknown as EditorBridge).getExtraSetting('logLevel')));
371: 
372:     const WORD_WRAP_KEY = 'calcpad.wordWrap';
373:     const initialWordWrap: 'on' | 'off' =
374:         localStorage.getItem(WORD_WRAP_KEY) === 'off' ? 'off' : 'on';
375:     const initialEditorFontFamily = (activeBridge as unknown as EditorBridge).getExtraSetting('editorFontFamily') ?? 'JuliaMono';
376:     let completionDelayMs = Number(activeBridge.getExtraSetting('completionDelayMs') ?? DEFAULT_COMPLETION_DELAY_MS);
377: 
378:     // ---- Editor groups ----
379:     // The desktop supports a single top/bottom split into two editor groups.
380:     // Each group owns a Monaco editor + a TabManager; `activeGroup`/`editor`/
381:     // `tabs` track the focused group and are reassigned on focus change so the
382:     // shared command/save/clipboard closures below always act on it.
383:     const groups = new Map<string, EditorGroup>();
384:     // Per-group wiring applied to every new group after the common wiring
385:     // (populated by the Tauri block: save commands, draft autosave, drop).
386:     const groupWireHooks: ((g: EditorGroup) => void)[] = [];
387:     let activeGroup!: EditorGroup;
388:     let editor!: monaco.editor.IStandaloneCodeEditor;
389:     let tabs!: TabManager;
390:     activeBridge.onRunErrors = errors => {
391:         const model = activeGroup.editor.getModel();
392:         if (model) setRunErrorMarkers(model, errors);
393:     };
394:     const historyCallbacks = { confirm: confirmLeaveUiDoc, restore: restoreNavigation };
395:     let navigationHistory: NavigationHistoryClient | undefined = isTauri
396:         ? undefined : createBrowserNavigationHistory(historyCallbacks);
397: 
398:     function recordNavigation(group: EditorGroup, jump = false): void {
399:         if (group !== activeGroup) return;
400:         const tabId = group.tabs.activeId;
401:         const position = group.editor.getPosition();
402:         const selection = group.editor.getSelection() ?? undefined;
403:         if (tabId && position) {
404:             navigationHistory?.record({ groupId: group.id, tabId, position, selection }, jump);
405:         }
406:     }
407: 
408:     function restoreNavigation(location: NavigationLocation): boolean {
409:         const group = groups.get(location.groupId);
410:         if (!group?.tabs.modelForTab(location.tabId)) return false;
411:         if (activeGroup !== group) setActiveGroup(group);
412:         group.tabs.activate(location.tabId);
413:         if (location.selection) {
414:             group.editor.setSelection(location.selection);
415:             group.editor.revealRangeInCenterIfOutsideViewport(group.editor.getSelection()!);
416:         } else {
417:             const position = group.editor.getModel()!.validatePosition(location.position);
418:             group.editor.setPosition(position);
419:             group.editor.revealPositionInCenterIfOutsideViewport(position);
420:         }
421:         group.editor.focus();
422:         return true;
423:     }
