425:     window.addEventListener('keydown', event => {
426:         const direction = navigationDirection(event, navigator.platform);
427:         if (!direction) return;
428:         event.preventDefault();
429:         event.stopImmediatePropagation();
430:         recordNavigation(activeGroup);
431:         void navigationHistory?.go(direction);
432:     }, true);
