484:     // ---- Group-scoped refresh helpers ----
485:     function markerToSeverityInfo(severity: monaco.MarkerSeverity) {
486:         switch (severity) {
487:             case monaco.MarkerSeverity.Error:
488:                 return { severityClass: 'lintError', icon: '✕' };
