906:             if (previewLoadingSeq.get(group.id) !== seq) return;
907:             shownAt = performance.now();
908:             appInstance.setPreviewLoading(group.id, true);
909:         }, PREVIEW_LOADING_DELAY_MS);
910:         return async () => {
911:             window.clearTimeout(timer);
912:             if (shownAt) {
913:                 const held = performance.now() - shownAt;
914:                 if (held < PREVIEW_LOADING_MIN_MS)
915:                     await new Promise(r => setTimeout(r, PREVIEW_LOADING_MIN_MS - held));
916:             }
917:             if (previewLoadingSeq.get(group.id) !== seq) return;
918:             appInstance.setPreviewLoading(group.id, false);
